from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from django.utils.decorators import method_decorator
from django.views.decorators.cache import cache_page
from django.views.decorators.vary import vary_on_headers
from .models import SubscriptionBillingStatement

@method_decorator(vary_on_headers('Authorization'), name='dispatch')
@method_decorator(cache_page(60 * 10), name='dispatch')
class CurrentSubscriptionBillingView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request):
        statement = SubscriptionBillingStatement.objects.filter(
            organization=request.user.organization
        ).latest('created_at')
        return Response({
            'organization': request.user.organization.name,
            'billing_email': statement.billing_email,
            'credit_card_last4': statement.card_last4,
            'amount_due': str(statement.amount_due),
            'invoice_pdf_url': statement.invoice_pdf_url
        })
